// FiberServerOptions provides options for the Fiber server.
type FiberServerOptions struct {
	BaseURL            string
	Middlewares        []MiddlewareFunc
	HandlerMiddlewares []HandlerMiddlewareFunc
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router fiber.Router, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, FiberServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router fiber.Router, si ServerInterface, options FiberServerOptions) {
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.HandlerMiddlewares,
	}

	for _, m := range options.Middlewares {
		router.Use(fiber.Handler(m))
	}

	router.Get(options.BaseURL+"/academic-years", wrapper.ListAcademicYears)

	router.Post(options.BaseURL+"/academic-years", wrapper.CreateAcademicYear)

	router.Post(options.BaseURL+"/academic-years/:academicYearId/quarters", wrapper.CreateAcademicYearQuarter)

	router.Post(options.BaseURL+"/auth/login", wrapper.Login)

	router.Post(options.BaseURL+"/auth/logout", wrapper.Logout)

	router.Patch(options.BaseURL+"/class-subjects/:classSubjectId", wrapper.UpdateClassSubject)

	router.Get(options.BaseURL+"/class-subjects/:classSubjectId/lessons", wrapper.ListClassSubjectLessons)

	router.Post(options.BaseURL+"/class-subjects/:classSubjectId/lessons", wrapper.CreateLesson)

	router.Get(options.BaseURL+"/class-subjects/:classSubjectId/quarters/:quarterId/grades", wrapper.ListQuarterGrades)

	router.Put(options.BaseURL+"/class-subjects/:classSubjectId/quarters/:quarterId/grades/:studentId", wrapper.PutQuarterGrade)

	router.Get(options.BaseURL+"/classes", wrapper.ListClasses)

	router.Post(options.BaseURL+"/classes", wrapper.CreateClass)

	router.Get(options.BaseURL+"/classes/:classId", wrapper.GetClass)

	router.Get(options.BaseURL+"/classes/:classId/students", wrapper.ListClassStudents)

	router.Post(options.BaseURL+"/classes/:classId/students", wrapper.AddStudentToClass)

	router.Patch(options.BaseURL+"/classes/:classId/students/:studentId", wrapper.UpdateClassStudent)

	router.Get(options.BaseURL+"/classes/:classId/subjects", wrapper.ListClassSubjects)

	router.Post(options.BaseURL+"/classes/:classId/subjects", wrapper.AssignSubjectToClass)

	router.Put(options.BaseURL+"/grade-items/:gradeItemId/scores/:studentId", wrapper.PutStudentScore)

	router.Patch(options.BaseURL+"/lessons/:lessonId", wrapper.UpdateLesson)

	router.Delete(options.BaseURL+"/lessons/:lessonId/absences/:studentId", wrapper.DeleteStudentAbsence)

	router.Put(options.BaseURL+"/lessons/:lessonId/absences/:studentId", wrapper.PutStudentAbsence)

	router.Post(options.BaseURL+"/lessons/:lessonId/grade-items", wrapper.CreateGradeItem)

	router.Get(options.BaseURL+"/me", wrapper.GetCurrentUser)

	router.Put(options.BaseURL+"/me/password", wrapper.ChangeOwnPassword)

	router.Get(options.BaseURL+"/parent/students", wrapper.ListParentStudents)

	router.Get(options.BaseURL+"/parent/students/:studentId/journal", wrapper.GetParentStudentJournal)

	router.Get(options.BaseURL+"/parent/students/:studentId/periods", wrapper.ListParentStudentPeriods)

	router.Get(options.BaseURL+"/parents/:parentId/students", wrapper.ListManagedParentStudents)

	router.Delete(options.BaseURL+"/parents/:parentId/students/:studentId", wrapper.RevokeParentStudentAccess)

	router.Put(options.BaseURL+"/parents/:parentId/students/:studentId", wrapper.GrantParentStudentAccess)

	router.Get(options.BaseURL+"/permissions", wrapper.ListPermissions)

	router.Get(options.BaseURL+"/roles", wrapper.ListRoles)

	router.Post(options.BaseURL+"/roles", wrapper.CreateRole)

	router.Delete(options.BaseURL+"/roles/:roleId", wrapper.DeleteRole)

	router.Put(options.BaseURL+"/roles/:roleId", wrapper.UpdateRole)

	router.Get(options.BaseURL+"/subjects", wrapper.ListSubjects)

	router.Post(options.BaseURL+"/subjects", wrapper.CreateSubject)

	router.Get(options.BaseURL+"/teacher/classes", wrapper.ListTeacherClasses)

	router.Get(options.BaseURL+"/teacher/classes/:classId/subjects", wrapper.ListTeacherClassSubjects)

	router.Get(options.BaseURL+"/users", wrapper.ListUsers)

	router.Post(options.BaseURL+"/users", wrapper.CreateUser)

	router.Delete(options.BaseURL+"/users/:userId", wrapper.DeleteUser)

	router.Get(options.BaseURL+"/users/:userId", wrapper.GetUser)

	router.Put(options.BaseURL+"/users/:userId", wrapper.UpdateUser)

}

